import { test, expect } from '@playwright/test';

test.describe('Username Availability Async Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/signup');
  });

  test('should display username availability when available', async ({ page }) => {
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('newuser123');

    const checkButton = page.getByRole('button', { name: /check availability/i });
    await checkButton.click();

    const availabilityMessage = page.getByText('Username is available');
    await expect(availabilityMessage).toBeVisible();

    const successIndicator = page.getByRole('status', { name: /available/i });
    await expect(successIndicator).toBeVisible();
  });

  test('should display username taken message when username is unavailable', async ({ page }) => {
    const usernameInput = page.getByLabel('Username');
    await usernameInput.fill('existinguser');

    const checkButton = page.getByRole('button', { name: /check availability/i });
    await checkButton.click();

    const takenMessage = page.getByText('Username is already taken');
    await expect(takenMessage).toBeVisible();

    const errorIndicator = page.getByRole('status', { name: /taken/i });
    await expect(errorIndicator).toBeVisible();
  });
});
